/**
 * Kira core HTTP+SSE client.
 *
 * Talks to `kira-cored` (Rust daemon) over `/v1/*`. All types come from
 * `agent/src/generated/*.ts` (auto-generated by ts-rs on `cargo test`).
 *
 * Bun-native: uses global `fetch` and SSE parsing via ReadableStream.
 */

import type {
  ChatRequest,
  ChatMessage,
  ChatResponse,
  StreamEvent,
} from "../generated/chat";
import type { BashRequest, BashResponse } from "../generated/bash";
import type {
  FileReadRequest,
  FileReadResponse,
  FileWriteRequest,
  FileWriteResponse,
} from "../generated/file";
import type {
  Agent,
  AgentKind,
  CancelResponse,
  SpawnAgentRequest,
} from "../generated/agent";

export interface CoreClientConfig {
  baseUrl: string; // default http://127.0.0.1:7777
  timeoutMs: number; // request timeout for non-streaming
}

export const DEFAULT_CONFIG: CoreClientConfig = {
  baseUrl: process.env.KIRA_CORE_URL ?? "http://127.0.0.1:7777",
  timeoutMs: 60_000,
};

/** Errors raised by the client. */
export class CoreError extends Error {
  constructor(
    message: string,
    public readonly status?: number,
    public readonly chain?: string,
  ) {
    super(message);
    this.name = "CoreError";
  }
}

async function parseError(res: Response): Promise<CoreError> {
  try {
    const body = (await res.json()) as { error?: string; chain?: string };
    return new CoreError(
      body.error ?? `HTTP ${res.status}`,
      res.status,
      body.chain,
    );
  } catch {
    return new CoreError(`HTTP ${res.status} ${res.statusText}`, res.status);
  }
}

export class CoreClient {
  constructor(public readonly config: CoreClientConfig = DEFAULT_CONFIG) {}

  // -----------------------------------------------------------------
  // Health
  // -----------------------------------------------------------------

  async health(): Promise<{
    status: string;
    version: string;
    uptime_secs: number;
  }> {
    const res = await fetch(`${this.config.baseUrl}/v1/health`, {
      signal: AbortSignal.timeout(this.config.timeoutMs),
    });
    if (!res.ok) throw await parseError(res);
    return res.json() as Promise<{
      status: string;
      version: string;
      uptime_secs: number;
    }>;
  }

  // -----------------------------------------------------------------
  // Chat (non-streaming)
  // -----------------------------------------------------------------

  async chat(req: ChatRequest): Promise<ChatResponse> {
    const res = await fetch(`${this.config.baseUrl}/v1/chat`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(req),
      signal: AbortSignal.timeout(this.config.timeoutMs),
    });
    if (!res.ok) throw await parseError(res);
    return res.json() as Promise<ChatResponse>;
  }

  // -----------------------------------------------------------------
  // Chat streaming (SSE)
  // -----------------------------------------------------------------

  /**
   * Stream chat tokens. Returns an async iterator of StreamEvent.
   *
   * Usage:
   *   for await (const ev of client.chatStream(req)) {
   *     if (ev.type === "token") process.stdout.write(ev.delta);
   *     if (ev.type === "done")  break;
   *   }
   */
  async *chatStream(req: ChatRequest): AsyncIterable<StreamEvent> {
    const res = await fetch(`${this.config.baseUrl}/v1/chat/stream`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(req),
    });
    if (!res.ok) throw await parseError(res);
    if (!res.body) throw new CoreError("no response body");

    const reader = res.body.getReader();
    const decoder = new TextDecoder();
    let buffer = "";

    while (true) {
      const { done, value } = await reader.read();
      if (done) break;
      buffer += decoder.decode(value, { stream: true });

      // SSE frames are separated by blank lines (\n\n).
      let sep: number;
      while ((sep = buffer.indexOf("\n\n")) !== -1) {
        const frame = buffer.slice(0, sep);
        buffer = buffer.slice(sep + 2);
        const event = parseSseFrame(frame);
        if (event) yield event;
      }
    }
  }

  // -----------------------------------------------------------------
  // Tools
  // -----------------------------------------------------------------

  async bash(req: BashRequest): Promise<BashResponse> {
    return this.postJson<BashResponse>("/v1/tool/bash", req);
  }

  async fileRead(req: FileReadRequest): Promise<FileReadResponse> {
    return this.postJson<FileReadResponse>("/v1/tool/file_read", req);
  }

  async fileWrite(req: FileWriteRequest): Promise<FileWriteResponse> {
    return this.postJson<FileWriteResponse>("/v1/tool/file_write", req);
  }

  // -----------------------------------------------------------------
  // Agents
  // -----------------------------------------------------------------

  async spawnAgent(req: SpawnAgentRequest): Promise<Agent> {
    return this.postJson<Agent>("/v1/agents/spawn", req);
  }

  async listAgents(): Promise<Agent[]> {
    const res = await fetch(`${this.config.baseUrl}/v1/agents`, {
      signal: AbortSignal.timeout(this.config.timeoutMs),
    });
    if (!res.ok) throw await parseError(res);
    return res.json() as Promise<Agent[]>;
  }

  async getAgent(id: string): Promise<Agent> {
    const res = await fetch(`${this.config.baseUrl}/v1/agents/${id}`, {
      signal: AbortSignal.timeout(this.config.timeoutMs),
    });
    if (!res.ok) throw await parseError(res);
    return res.json() as Promise<Agent>;
  }

  async cancelAgent(id: string): Promise<CancelResponse> {
    return this.postJson<CancelResponse>(`/v1/agents/${id}/cancel`, {});
  }

  // -----------------------------------------------------------------
  // Internals
  // -----------------------------------------------------------------

  private async postJson<T>(path: string, body: unknown): Promise<T> {
    const res = await fetch(`${this.config.baseUrl}${path}`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(body),
      signal: AbortSignal.timeout(this.config.timeoutMs),
    });
    if (!res.ok) throw await parseError(res);
    return res.json() as Promise<T>;
  }
}

/**
 * Parse a single SSE frame into a StreamEvent.
 * Frame format:
 *   event: token
 *   data: {"type":"token","delta":"..."}
 */
function parseSseFrame(frame: string): StreamEvent | null {
  const lines = frame.split("\n");
  let data: string | null = null;
  for (const line of lines) {
    if (line.startsWith("data:")) {
      data = line.slice(5).trimStart();
    }
  }
  if (!data) return null;
  try {
    return JSON.parse(data) as StreamEvent;
  } catch {
    return null;
  }
}

// Re-exports for ergonomic imports.
export type {
  ChatRequest,
  ChatMessage,
  ChatResponse,
  StreamEvent,
  BashRequest,
  BashResponse,
  FileReadRequest,
  FileReadResponse,
  FileWriteRequest,
  FileWriteResponse,
  Agent,
  AgentKind,
  CancelResponse,
  SpawnAgentRequest,
};
